import numpy as np


def carr_madan_call(cf, K, r, T, alpha=1.5, v_max=200, n=20001):
    v = np.linspace(0, v_max, n)
    k = np.log(K)
    den = alpha ** 2 + alpha - v ** 2 + 1j * (2 * alpha + 1) * v
    psi = np.exp(-r * T) * cf(v - (alpha + 1) * 1j) / den
    return np.exp(-alpha * k) / np.pi * np.trapezoid((np.exp(-1j * v * k) * psi).real, v)


def merton_cf(u, S0, r, sigma, T, lam, mu_j, delta_j):
    kappa = np.exp(mu_j + delta_j ** 2 / 2) - 1
    m = np.log(S0) + (r - sigma ** 2 / 2 - lam * kappa) * T
    jumps = lam * T * (np.exp(1j * u * mu_j - delta_j ** 2 * u ** 2 / 2) - 1)
    return np.exp(1j * u * m - sigma ** 2 * T * u ** 2 / 2 + jumps)
